        assertEquals("٢٤٫٠٠ US$", PriceFormatter(Locale("ar")).format(2400))
    }
}

class FakePaymentApi : PaymentApi {
    var calls = 0; private set
    var failWith: Exception? = null
    var delayMs = 0L
    val received = mutableListOf<PaymentRequest>()

    override suspend fun pay(request: PaymentRequest): PaymentResult {
        calls++
        received += request
        delay(delayMs)                                   // virtual time in runTest
        failWith?.let { throw it }
        return PaymentResult(id = "pay_$calls", status = "succeeded")
    }
}

// MockK for a third-party type that is awkward to fake
@Test fun logsPurchaseToAnalytics() = runTest {
    val analytics = mockk<FirebaseAnalytics>(relaxed = true)
    val vm = CheckoutViewModel(FakeCartRepository(), FakePaymentApi(), analytics)
    vm.onPay(); advanceUntilIdle()
    verify(exactly = 1) { analytics.logEvent("purchase", any()) }
}

class SearchViewModelTest {
    @get:Rule val main = MainDispatcherRule(StandardTestDispatcher())

    @Test fun showsResultsAfterDebounce() = runTest {
        val repo = FakeSearchRepository(results = mapOf("kotlin" to listOf("Kotlin in Action")))
        val vm = SearchViewModel(repo)

        vm.state.test {
            assertEquals(SearchState(), awaitItem())                     // initial
            vm.onQuery("kotlin")
            advanceTimeBy(301)
            assertEquals(SearchState(query = "kotlin", loading = true), awaitItem())
            assertEquals(SearchState(query = "kotlin", results = listOf("Kotlin in Action")), awaitItem())
        }
    }

    @Test fun emptyQueryClearsResults() = runTest {
        val vm = SearchViewModel(FakeSearchRepository())
        vm.onQuery("")
        advanceUntilIdle()
        assertEquals(emptyList<String>(), vm.state.value.results)
    }
}

class OrderRepositoryTest {
    private val server = MockWebServer()
    private val dao = FakeOrderDao()
    private lateinit var repo: OrderRepository

    @Before fun setUp() { server.start(); repo = OrderRepository(api(server.url("/")), dao) }
    @After fun tearDown() = server.shutdown()

    @Test fun refreshFailureKeepsCachedOrders() = runTest {
        dao.insert(orderEntity("A1"))
        server.enqueue(MockResponse().setResponseCode(503))
        val result = repo.refresh()
        assertTrue(result.isFailure)
        assertEquals(listOf("A1"), dao.all().map { it.id })
    }
}

class ProfileViewModelTest {
    @get:Rule val main = MainDispatcherRule()

    @Test fun signOutNavigatesToLogin() = runTest {
        val auth = mockk<AuthRepository> { coEvery { signOut() } just Runs }
        val vm = ProfileViewModel(auth)
        vm.events.test {
            vm.onSignOut()
            assertEquals(ProfileEvent.GoToLogin, awaitItem())
            expectNoEvents()
        }
        coVerify(exactly = 1) { auth.signOut() }
    }
}

