// Defer non-essential startup work.
class App : Application() {
    @Inject lateinit var analytics: Lazy<Analytics>          // created on first use, not at startup
    override fun onCreate() {
        super.onCreate()
        ProcessLifecycleOwner.get().lifecycleScope.launch(Dispatchers.Default) {
            RemoteConfig.fetchAndActivate()                    // off the main thread
        }
    }
}

