@Immutable
data class ArticleUi(val id: String, val title: String, val source: String, val imageUrl: String?)

@Composable
fun ArticleList(articles: List<ArticleUi>, listState: LazyListState = rememberLazyListState()) {
    val showTopButton by remember { derivedStateOf { listState.firstVisibleItemIndex > 5 } }   // not every scroll pixel
    Box {
        LazyColumn(state = listState) {
            items(articles, key = { it.id }, contentType = { "article" }) { ArticleRow(it) }
        }
        if (showTopButton) ScrollToTopButton(listState)
    }
}

@Composable
fun CollapsingHeader(scroll: () -> Int) {
    // Read scroll in the layout phase lambda: no recomposition on every frame.
    Box(Modifier.offset { IntOffset(0, -scroll() / 2) }) { HeaderImage() }
}

object Diagnostics {
    private val crashlytics get() = Firebase.crashlytics

    fun screen(name: String) {
        crashlytics.setCustomKey("screen", name)
        crashlytics.log("screen:$name")
    }

    fun flags(flags: Map<String, Boolean>) = flags.forEach { (k, v) -> crashlytics.setCustomKey("flag_$k", v) }

    fun signedIn(pseudonymousId: String) = crashlytics.setUserId(pseudonymousId)   // never an email

    fun nonFatal(e: Throwable, where: String) {
        crashlytics.log("non-fatal in $where")
        crashlytics.recordException(e)
    }
}

